import{_ as t,o as a,c as i,a0 as n}from"./chunks/framework.DYS8d9tm.js";const m=JSON.parse('{"title":"✨ WealthFam Features","description":"","frontmatter":{},"headers":[],"relativePath":"user/features.md","filePath":"user/features.md"}'),r={name:"user/features.md"};function o(s,e,l,c,u,d){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="✨-wealthfam-features" tabindex="-1">✨ WealthFam Features <a class="header-anchor" href="#✨-wealthfam-features" aria-label="Permalink to &quot;✨ WealthFam Features&quot;">​</a></h1><p>A comprehensive overview of what you can achieve with WealthFam.</p><h2 id="📊-holistic-dashboard" tabindex="-1">📊 Holistic Dashboard <a class="header-anchor" href="#📊-holistic-dashboard" aria-label="Permalink to &quot;📊 Holistic Dashboard&quot;">​</a></h2><ul><li><strong>Real-time Balance Sheet</strong>: Instantly view Net Worth, Liquidity, and Debt.</li><li><strong>Spending Velocity</strong>: Sparklines and category breakdowns.</li></ul><h2 id="📈-mutual-funds-tracking" tabindex="-1">📈 Mutual Funds Tracking <a class="header-anchor" href="#📈-mutual-funds-tracking" aria-label="Permalink to &quot;📈 Mutual Funds Tracking&quot;">​</a></h2><ul><li><strong>XIRR &amp; Performance</strong>: Automated tracking.</li><li><strong>Unified Portfolio</strong>: Manage multiple folios.</li></ul><h2 id="🧠-ai-intelligence" tabindex="-1">🧠 AI Intelligence <a class="header-anchor" href="#🧠-ai-intelligence" aria-label="Permalink to &quot;🧠 AI Intelligence&quot;">​</a></h2><ul><li><strong>Smart Categorization</strong>: Automated classification.</li><li><strong>Deep Insights</strong>: Gemini-powered analytics.</li></ul><h2 id="🕒-subscription-management" tabindex="-1">🕒 Subscription Management <a class="header-anchor" href="#🕒-subscription-management" aria-label="Permalink to &quot;🕒 Subscription Management&quot;">​</a></h2><ul><li><strong>Recurring Transactions</strong>: Factor billing into liquidity.</li></ul><h2 id="🏦-specialized-financial-instruments" tabindex="-1">🏦 Specialized Financial Instruments <a class="header-anchor" href="#🏦-specialized-financial-instruments" aria-label="Permalink to &quot;🏦 Specialized Financial Instruments&quot;">​</a></h2><ul><li><strong>Fixed &amp; Recurring Deposits</strong>: Track deposits with automated compounding interest simulation, tenure timelines, and maturity projections.</li><li><strong>Provident Funds (EPF / PPF / NPS)</strong>: Tripartite EPF split (Employee, Employer, Pension), annual statutory interest estimation, and post-tax statutory deposit tracking (₹1.5L annual ceiling).</li><li><strong>Credit Cards</strong>: Track statement cycles (<code>current_unbilled</code>, <code>last_statement</code>), utilization health, bill due dates, and minimum payments due.</li><li><strong>Loans &amp; EMIs</strong>: Manage lenders, track loan account numbers, and monitor EMI debits.</li></ul><h2 id="🔄-cross-account-transfers-pairing" tabindex="-1">🔄 Cross-Account Transfers &amp; Pairing <a class="header-anchor" href="#🔄-cross-account-transfers-pairing" aria-label="Permalink to &quot;🔄 Cross-Account Transfers &amp; Pairing&quot;">​</a></h2><ul><li><strong>Automated Match Detection</strong>: Smart heuristic engine detects funds moving between your own accounts (e.g. Bank to Card bill payment or savings transfers).</li><li><strong>Zero Expense Inflation</strong>: Paired transfers are automatically excluded from spending analytics, keeping cash flow reports accurate.</li><li><strong>1-Click Counterpart Leg Generation</strong>: Auto-generate missing receiving credits directly with adjustable amounts for cashback or payment discounts.</li></ul><h2 id="📂-document-vault-attachments" tabindex="-1">📂 Document Vault &amp; Attachments <a class="header-anchor" href="#📂-document-vault-attachments" aria-label="Permalink to &quot;📂 Document Vault &amp; Attachments&quot;">​</a></h2><ul><li><strong>Hierarchical Storage</strong>: Organize tax forms, receipts, and investment documents in nested folders.</li><li><strong>Transaction Linking</strong>: Attach receipts and invoices directly to transactions with in-app PDF and image previews.</li></ul><h2 id="📱-mobile-app-android" tabindex="-1">📱 Mobile App (Android) <a class="header-anchor" href="#📱-mobile-app-android" aria-label="Permalink to &quot;📱 Mobile App (Android)&quot;">​</a></h2><ul><li><strong>Real-time Ingestion</strong>: Automated SMS financial alert capture with high-accuracy GPS tagging.</li><li><strong>Mobile Transfers Hub</strong>: Approve detected transfers in bulk and create counterpart legs on the go.</li><li><strong>Dedicated Instrument Views</strong>: Instant mobile access to Deposits, Provident Funds, and Credit Cards.</li><li><strong>Active Expense Group Assignment</strong>: Group assignment picker cleanly filters out archived groups while preserving historical assignments.</li><li><strong>Living vs Total Spend Alignment</strong>: Ledger spend headers explicitly reconcile operational living spending against investments and internal transfers with clear tooltip breakdowns.</li></ul><h2 id="🏦-bulk-statement-reconciliation" tabindex="-1">🏦 Bulk Statement Reconciliation <a class="header-anchor" href="#🏦-bulk-statement-reconciliation" aria-label="Permalink to &quot;🏦 Bulk Statement Reconciliation&quot;">​</a></h2><ul><li><strong>Smart PDF Ingestion</strong>: Specialized parsers for bank statements (e.g., HDFC, Swiggy HDFC) and eCAS portfolios.</li><li><strong>Automated Rule Persistence</strong>: Generate classification rules directly from ingestion flows with PostgreSQL-safe JSON keyword queries.</li><li><strong>Bulk Triage &amp; Normalized Categories</strong>: Confirm hundreds of transactions in seconds with searchable category selection (<code>:teleport=&quot;true&quot;</code> to prevent container clipping) and leaf-category normalization.</li><li><strong>Pending Triage Auto-Promotion</strong>: Reconciling statement transactions automatically resolves matching pending triage items into official ledger records.</li><li><strong>Category Rules Review Prioritization</strong>: Rules matching pending triage items are automatically pinned to the top of the rules list with amber badges (<code>⚡ X in Review</code>) and quick-filter toggles.</li></ul>',20)])])}const h=t(r,[["render",o]]);export{m as __pageData,h as default};
